 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Panels are separated by uniform full-width/full-height lines.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(length, separators):
        out, start = [], 0
        for p in separators:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < length:
            out.append((start, length))
        return out

    rows, cols = segments(h, sep_rows), segments(w, sep_cols)
    # Non-background pixels form two-mark panels; global background is most frequent.
    vals = [grid[r][c] for r0, r1 in rows for c0, c1 in cols
            for r in range(r0, r1) for c in range(c0, c1)]
    background = Counter(vals).most_common(1)[0][0]
    return [[int(sum(grid[r][c] != background for r in range(r0, r1)
                     for c in range(c0, c1)) == 2)
             for c0, c1 in cols] for r0, r1 in rows]
